INSERT INTO `issue_status` (`status_id`, `status`, `description`, `sms_msg`, `email_msg`) VALUES
(1, 'New', 'Newly created report by logon user', 'Your report has been captured and the assigned status_id  is {_status_id }. You can contact us on 0558886366 or visit https://maaro.org for more information', 'Thank you for contacting us, your report status_id  is {_status_id }. You will soon be notified on the details of it. Kindly visit https://maaro.org for information'),
(2, 'Submitted', 'report from the website or logon user', 'Your report {_status_id } was submitted. You can contact us on 0558886366 or visit https://maaro.org for further information', 'Thank you for contacting us, your report status_id  is {_status_id }. You will soon be notified on the details of it. Visit us on https://maaro.org for information. You can also check the status of you report<a href=\'https://maaro.org/complaint/gcwebstate.aspx\'><strong>Here</strong></a>'),
(3, 'Received', 'The report is duly received and awaits processing', 'Thank you for contacting us, Your report {_status_id } has been received. You can contact us on 0558886366 or  https://maaro.org for further info.', 'Thank you for contacting us, your report {_status_id } was received by one of staff. You will soon be notified on the details of it. Visit us on https://maaro.org for information. You can also check the status of the report <a href=\'https://maaro.org/complaint/gcwebstate.aspx\'><strong>Here</strong></a>'),
(4, 'Processed', 'The report is processed and its awaiting resolution', 'Your report {_status_id } has been processed for resolution. You can contact us on 0558886366 or https://maaro.org for further info.', 'Your report {_status_id } was processed by for resolution. You will soon be notified on the status of it soon. Visit us on https://maaro.org for information. You can also check the status of the report on <a href=\'https://maaro.org/complaint/gcwebstate.apsx\'><strong>Here</strong></a>'),
(5, 'Resolved', 'The report is resolved but awaits acknowledgement from the reporter to the veracity of the resolution', 'Your report {_status_id } has been resolved. Please can contact us on 0558886366 or https://maaro.org/ if you are not satisfied.', 'Your report {_status_id } was resolved. You will soon be contacted by one of staff for your confirmation. You can also visit us on https://maaro.org for information. You can also check the status of the report on <a href=\'https://cems.isodec.org/Complaint/gcwebstate.aspx\'><strong>Here</strong></a>'),
(6, 'Closed', 'The report is closed either through resolution or due to other means', 'Your report {_status_id } has now been closed. We thank you for contacting us. You can always call on us on 0558886366 or visit our site', 'Your report {_status_id } has now been closed following your confirmation from our staff. We will like to thank you so much for contacting us. You can always call on us on 0558886366 or visit our site <a href=\'https://maaro.org/complaint/gcwebstate.aspx\'><strong>Here</strong></a> for more information'),
(7, 'Reopened', 'Reopened', '', '');
